function bookingValid(data,s){const today=new Date(Date.now()+3*3600000).toISOString().slice(0,10);if(!s.bookingEnabled)fail(409,'الحجز متوقف مؤقتًا.');if(!/^\d{4}-\d{2}-\d{2}$/.test(data.date)||data.date<today||!Number.isFinite(Date.parse(data.date+'T12:00:00Z'))||new Date(data.date+'T12:00:00Z').toISOString().slice(0,10)!==data.date||s.closedDays.includes(new Date(data.date+'T12:00:00Z').getUTCDay())||s.blockedDates.includes(data.date))fail(400,'اختاري تاريخ زيارة متاحًا.');if(!/^\d{2}:00$/.test(data.time)||Number(data.time.slice(0,2))<s.openTime||Number(data.time.slice(0,2))>=s.closeTime)fail(400,'اختاري وقتًا ضمن ساعات العمل.');if(!/^\d{4}-\d{2}-\d{2}$/.test(data.wedding)||!Number.isFinite(Date.parse(data.wedding+'T12:00:00Z'))||new Date(data.wedding+'T12:00:00Z').toISOString().slice(0,10)!==data.wedding||data.wedding<data.date)fail(400,'موعد الزيارة يجب أن يسبق الزفاف.');if(Date.parse(data.date+'T'+data.time+':00+03:00')<=Date.now())fail(400,'اختاري موعدًا في المستقبل.');if(!s.services.includes(data.service))fail(400,'اختاري خدمة متاحة.')}
async function submission(request,env,kind){await rate(request,env);const d=await body(request,12000);if(d.website)fail(400,'تعذر إرسال الطلب.');const dedupe=text(request.headers.get('idempotency-key'),100,true);if(!/^[a-f0-9-]{36}$/.test(dedupe))fail(400,'أعيدي تحميل النموذج.');const existing=await statement(env,'SELECT id FROM requests WHERE dedupe = ?',dedupe).first();if(existing)return json({id:existing.id});
 let value;if(kind==='bookings'){const {data:site}=await content(env);value={name:text(d.name,100,true),phone:text(d.phone,15,true),wedding:text(d.wedding,10,true),date:text(d.date,10,true),time:text(d.time,5,true),service:text(d.service,100,true),dress:text(d.dress||'',60),notes:text(d.notes||'',1500)};if(!/^05[0-9]{8}$/.test(value.phone))fail(400,'أدخلي جوالًا سعوديًا يبدأ بـ05.');bookingValid(value,site.settings);if(value.dress&&!site.dresses.some(x=>x.id===value.dress&&x.published))fail(400,'الفستان غير متاح.');}
 else if(kind==='messages')value={name:text(d.name,100,true),email:email(d.email),subject:text(d.subject,150,true),message:text(d.message,2500,true)};
 else value={email:email(d.email)};
 const key=id(),date=now();try{await statement(env,'INSERT INTO requests (id,kind,data,status,notes,created,updated,version,dedupe) VALUES (?,?,?,\'new\',\'\',?,?,1,?)',key,kind,JSON.stringify(value),date,date,dedupe).run()}catch(e){const retry=await statement(env,'SELECT id FROM requests WHERE dedupe = ?',dedupe).first();if(retry)return json({id:retry.id});throw e}return json({id:key},201);
}
export async function api(request,env){const url=new URL(request.url),path=url.pathname,method=request.method;
 if(method!=='GET'&&method!=='HEAD')sameOrigin(request);
 if(path==='/api/catalog'&&method==='GET'){const c=await content(env);return json({data:publicContent(c.data),revision:c.revision})}
 if(/^\/api\/(bookings|messages|subscribers)$/.test(path)&&method==='POST')return submission(request,env,path.split('/').pop());
 const user=await identity(request,env);
 if(path==='/api/admin/me'&&method==='GET')return json(user);
 if(path==='/api/admin/content'){
  allow(user,['owner','editor']);if(method==='GET')return json(await content(env));
  if(method==='PUT'){const b=await body(request);const data=validateData(b.data);if(!Number.isInteger(b.revision))fail(400,'إصدار غير صالح.');const t=now();let result;if(b.revision===0)result=await statement(env,'INSERT OR IGNORE INTO content (id,data,revision,updated) VALUES (?,?,1,?)','site',JSON.stringify(data),t).run();else result=await statement(env,'UPDATE content SET data = ?,revision = revision + 1,updated = ? WHERE id = ? AND revision = ?',JSON.stringify(data),t,'site',b.revision).run();if(!result.meta.changes)fail(409,'عدّل شخص آخر المحتوى. احتفظي بتعديلاتك وأعيدي تحميل أحدث نسخة.');await log(env,user,'content.save','site');return json({revision:b.revision+1})}
 }
 if(path==='/api/admin/requests'&&method==='GET'){allow(user,['owner','reception']);const rows=await statement(env,'SELECT * FROM requests ORDER BY created DESC LIMIT 5000').all();return json(rows.results.map(x=>({...x,data:JSON.parse(x.data)})))}
 if(path.startsWith('/api/admin/requests/')){allow(user,['owner','reception']);const key=path.split('/').pop();if(method==='DELETE'){allow(user,['owner']);await statement(env,'DELETE FROM requests WHERE id = ?',key).run();await log(env,user,'request.delete',key);return json({ok:true})}if(method==='PATCH'){const b=await body(request,10000);if(!['new','confirmed','completed','cancelled','read','archived'].includes(b.status)||!Number.isInteger(b.version))fail(400,'حالة غير صالحة.');const old=await statement(env,'SELECT * FROM requests WHERE id = ?',key).first();if(!old)fail(404,'الطلب غير موجود.');if(old.kind==='bookings'&&!['new','confirmed','completed','cancelled'].includes(b.status))fail(400,'حالة حجز غير صحيحة.');if(old.kind!=='bookings'&&!['new','read','archived'].includes(b.status))fail(400,'حالة طلب غير صحيحة.');const notes=text(b.notes||'',3000);const updatedData=JSON.parse(old.data);if(old.kind==='bookings'&&b.appointment){updatedData.date=text(b.appointment.date,10,true);updatedData.time=text(b.appointment.time,5,true);const site=await content(env);bookingValid(updatedData,site.data.settings)}let sql='UPDATE requests SET status = ?,notes = ?,data = ?,updated = ?,version = version + 1 WHERE id = ? AND version = ?',args=[b.status,notes,JSON.stringify(updatedData),now(),key,b.version];if(old.kind==='bookings'&&b.status==='confirmed'){const c=await content(env),d=updatedData;bookingValid(d,c.data.settings);sql+=' AND (SELECT COUNT(*) FROM requests WHERE kind = \'bookings\' AND status = \'confirmed\' AND id <> ? AND json_extract(data,\'$.date\') = ? AND json_extract(data,\'$.time\') = ?) < ?';args.push(key,d.date,d.time,c.data.settings.slotCapacity)}const r=await statement(env,sql,...args).run();if(!r.meta.changes)fail(409,'تغيّر الطلب أو وصل الموعد إلى سعته المحددة. حدّثي القائمة.');await log(env,user,'request.'+b.status,key);return json({ok:true})}}
 if(path==='/api/admin/media'){allow(user,['owner','editor']);if(method==='GET'){const rows=await statement(env,'SELECT * FROM media ORDER BY created DESC').all();return json(rows.results.map(x=>({...x,url:'/media/'+x.id})))}if(method==='POST'){if(!env.BUCKET)fail(503,'مكتبة الصور غير متاحة.');if(Number(request.headers.get('content-length'))>12582912)fail(413,'الحد الأقصى للصورة 10 ميجابايت.');const payload=await readBytes(request,11534336);const form=await new Response(payload,{headers:{'Content-Type':request.headers.get('content-type')}}).formData(),file=form.get('file');if(!file||typeof file.arrayBuffer!=='function'||file.size>10485760)fail(400,'اختاري صورة لا تتجاوز 10 ميجابايت.');const bytes=new Uint8Array(await file.arrayBuffer());const jpg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255,png=bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71,webp=String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';const type=jpg?'image/jpeg':png?'image/png':webp?'image/webp':null;if(!type)fail(400,'الصور المدعومة JPG وPNG وWebP.');const key=id();await env.BUCKET.put(key,bytes,{httpMetadata:{contentType:type}});try{await statement(env,'INSERT INTO media (id,name,type,size,created) VALUES (?,?,?,?,?)',key,text(file.name,200),type,file.size,now()).run()}catch(e){await env.BUCKET.delete(key);throw e}await log(env,user,'media.upload',key);return json({id:key,url:'/media/'+key,name:file.name,type,size:file.size},201)}}
 if(path.startsWith('/api/admin/media/')&&method==='DELETE'){allow(user,['owner','editor']);const key=path.split('/').pop(),c=await content(env);if(JSON.stringify(c.data).includes('/media/'+key))fail(409,'الصورة مستخدمة في الموقع. استبدليها أولًا.');await env.BUCKET.delete(key);await statement(env,'DELETE FROM media WHERE id = ?',key).run();await log(env,user,'media.delete',key);return json({ok:true})}
 if(path==='/api/admin/members'){allow(user,['owner']);if(method==='GET')return json((await statement(env,'SELECT email,name,role,created FROM members ORDER BY created').all()).results);if(method==='POST'){const b=await body(request,5000),mail=email(b.email);if(mail===env.ADMIN_OWNER_EMAIL.toLowerCase())fail(400,'لا يمكن تغيير صلاحية مالك الموقع.');if(!['editor','reception'].includes(b.role))fail(400,'صلاحية غير صحيحة.');await statement(env,'INSERT INTO members (email,role,name,created) VALUES (?,?,?,?) ON CONFLICT(email) DO UPDATE SET role=excluded.role,name=excluded.name',mail,b.role,text(b.name||'',100),now()).run();await log(env,user,'member.save',mail);return json({ok:true})}}
 if(path.startsWith('/api/admin/members/')&&method==='DELETE'){allow(user,['owner']);const mail=decodeURIComponent(path.split('/').pop());if(mail===env.ADMIN_OWNER_EMAIL.toLowerCase())fail(400,'لا يمكن حذف المالك.');await statement(env,'DELETE FROM members WHERE email = ?',mail).run();await log(env,user,'member.delete',mail);return json({ok:true})}
 if(path==='/api/admin/audit'&&method==='GET'){allow(user,['owner']);return json((await statement(env,'SELECT * FROM audit ORDER BY created DESC LIMIT 200').all()).results)}
 fail(404,'المسار غير موجود.');
}
export default {async fetch(request,env){try{const u=new URL(request.url);if(u.pathname.startsWith('/api/'))return await api(request,env);if(u.pathname.startsWith('/media/')){if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405});const key=u.pathname.slice(7);if(!/^[a-f0-9-]{36}$/.test(key))fail(404,'الصورة غير موجودة.');const object=await env.BUCKET?.get(key);if(!object)fail(404,'الصورة غير موجودة.');return new Response(request.method==='HEAD'?null:object.body,{headers:{'Content-Type':object.httpMetadata?.contentType||'application/octet-stream','Cache-Control':'public,max-age=86400','X-Content-Type-Options':'nosniff'}})}
 if(u.pathname==='/admin'||u.pathname==='/admin.html'){await identity(request,env);u.pathname='/admin.html'}
 else if(!u.pathname.split('/').pop().includes('.')){u.pathname=u.pathname==='/'?'/index.html':u.pathname+'.html'}
 const response=await env.ASSETS.fetch(new Request(u,request));const h=new Headers(response.headers);h.set('X-Content-Type-Options','nosniff');h.set('Referrer-Policy','strict-origin-when-cross-origin');if(u.pathname.endsWith('.html'))h.set('Cache-Control','no-cache');return new Response(response.body,{status:response.status,headers:h});
 }catch(e){if(e.status===401&&!new URL(request.url).pathname.startsWith('/api/'))return Response.redirect(new URL('/signin-with-chatgpt?return_to=%2Fadmin',request.url),302);if(!e.status)console.error('Request failed',e.message);return json({error:e.status?e.message:'تعذر إتمام العملية. حاولي مجددًا.'},e.status||500)}}};
export {validateData,content,identity,bookingValid};
